style.css:
@keyframes gooEffect {
  0% {
    background-position: 0% 0%;
  }
  50% {
    background-position: 100% 100%;
  }
  100% {
    background-position: 0% 0%;
  }
}

body {
  background-color: black; /* Set the background color to black */
  background-image: linear-gradient(45deg, #000000, #6a0dad); /* Purple gradient with black */
  background-size: 400% 400%; /* Make the gradient large to create a smooth animation */
  animation: gooEffect 5s ease infinite; /* Animation to move the gradient */
  overflow: hidden; /* Prevent overflow of any extra animation */
  height: 100vh; /* Full height of the viewport */
  margin: 0; /* Remove any default margin */
}

html {
  height: 100%;
  width: 100%;
}
